"""Phase 1 MOCK matching + classification (step 3a). Generated by code, NOT by an AI model.

Derived from the Capability Locker proof status and values (SPEC §18), so the built-in gaps of P1–P3 show up in the
checklist. Output schema = ComparisonOutput (Phase 2). Readiness and indication that follow are the real code.
"""
from __future__ import annotations

from datetime import date

from .. import schemas
from ..util import add_months, parse_date
from .screening import field

MOCK_MODEL = "none (mock generated by code)"
M = 1_000_000


def item(req_id, locker, status, conf, en, nb, cen, cnb, part=None):
    d = {"req_id": req_id, "locker_field": locker, "match_status": status, "match_confidence": conf,
         "reason_en": en, "reason_nb": nb, "confidence_reason_en": cen, "confidence_reason_nb": cnb}
    return d, part


def classify(req: dict, check: dict, profile: dict, deadline: date) -> tuple[dict, str | None]:
    rid, rule = req["req_id"], check.get("rule")
    f = lambda k: field(profile, k)  # noqa: E731

    if rule == "tax":
        e = f("tax_vat_certificate")
        issued = parse_date(e["structured"]["issue_date"])
        valid = add_months(issued, 6) >= deadline
        return item(rid, "tax_vat_certificate", "met", "high",
                    f"Tax and VAT certificate held (issued {issued})" + ("" if valid else
                                                                         "; older than six months at the deadline"),
                    f"Skatteattest finnes (utstedt {issued})" + ("" if valid else "; eldre enn seks måneder ved fristen"),
                    "Field and issue date are explicit", "Feltet og utstedelsesdatoen er entydige")
    if rule == "hms":
        e = f("hms_declaration")
        if e["proof_status"] == "Documented":
            return item(rid, "hms_declaration", "met", "high", "Signed HMS self-declaration on file",
                        "Signert HMS-egenerklæring finnes", "Documented field", "Dokumentert felt")
        return item(rid, "hms_declaration", "met", "medium", "HMS system stated as in place, no signed document",
                    "HMS-system oppgitt å være på plass, uten signert dokument",
                    "Only self-declared", "Kun egenerklært")
    if rule == "turnover":
        e = f("turnover")
        years = sorted(e["structured"]["by_year_nok"].items())[-3:]
        ok = [y for y, v in years if v >= check["min_nok"]]
        lst = ", ".join(f"{y}: {v / M:g}" for y, v in years)
        if len(ok) == len(years):
            return item(rid, "turnover", "met", "high", f"Turnover last three years (NOK m) {lst} ≥ {check['min_nok'] / M:g}",
                        f"Omsetning siste tre år (NOK mill.) {lst} ≥ {check['min_nok'] / M:g}",
                        "Documented annual accounts; plain comparison", "Dokumenterte årsregnskap; enkel sammenligning")
        if ok:
            return item(rid, "turnover", "partly_met", "medium",
                        f"Turnover reaches NOK {check['min_nok'] / M:g}m only in {', '.join(ok)} ({lst})",
                        f"Omsetningen når NOK {check['min_nok'] / M:g} mill. bare i {', '.join(ok)} ({lst})",
                        "Depends on how the buyer reads 'each of the last three years'",
                        "Avhenger av hvordan oppdragsgiver leser «hvert av de tre siste årene»")
        near = max(v for _, v in years) >= 0.8 * check["min_nok"]
        return item(rid, "turnover", "not_met", "medium" if near else "high",
                    f"Turnover below NOK {check['min_nok'] / M:g}m in all of the last three years ({lst})",
                    f"Omsetningen er under NOK {check['min_nok'] / M:g} mill. alle de tre siste årene ({lst})",
                    "Close to the minimum" if near else "Clear gap", "Nær minimumskravet" if near else "Tydelig avvik")
    if rule == "credit":
        e = f("credit_rating")
        if e["proof_status"] == "Declared missing":
            return item(rid, "credit_rating", "lacks_data", "medium", "Credit rating declared missing by the firm",
                        "Kredittvurdering er erklært manglende av firmaet",
                        "Firm opted out explicitly; financial capacity may be shown otherwise",
                        "Firmaet har reservert seg; økonomisk kapasitet kan kanskje vises på annen måte")
        return item(rid, "credit_rating", "met", "high", f"Credit rating {e['structured']['rating']} on file",
                    f"Kredittvurdering {e['structured']['rating']} finnes", "Documented field", "Dokumentert felt")
    if rule == "insurance":
        e = f("insurance")
        cov = e["structured"]["coverage_nok"]
        if cov >= check["min_nok"]:
            return item(rid, "insurance", "met", "high", f"{e['structured']['type']}: NOK {cov / M:g}m per claim",
                        f"{e['structured']['type']}: NOK {cov / M:g} mill. per skade", "Documented coverage",
                        "Dokumentert dekning")
        return item(rid, "insurance", "not_met", "high",
                    f"Coverage NOK {cov / M:g}m is below the required NOK {check['min_nok'] / M:g}m",
                    f"Dekning NOK {cov / M:g} mill. er under kravet på NOK {check['min_nok'] / M:g} mill.",
                    "Documented coverage below the minimum", "Dokumentert dekning under minimum")
    if rule == "references":
        refs = [e for e in profile["capability_locker"] if e["id"].startswith("reference_")]
        strong, small, related = [], [], []
        for e in refs:
            s = e["structured"]
            if any(s["cpv"].startswith(p) for p in check["prefixes"]):
                (strong if s["value_nok"] >= check["min_value"] else small).append(e)
            elif any(s["cpv"][:2] == p[:2] for p in check["prefixes"]):
                related.append(e)
        n = check["n"]
        ids = lambda xs: ", ".join(x["id"] for x in xs) or "none"  # noqa: E731
        if len(strong) >= n:
            documented = [e for e in strong if e["proof_status"] == "Documented"]
            conf = "high" if len(documented) >= n else "medium"
            return item(rid, ids(strong), "met", conf, f"{len(strong)} comparable references ({ids(strong)})",
                        f"{len(strong)} sammenlignbare referanser ({ids(strong)})",
                        "All documented by reference letters" if conf == "high" else "Some references only self-declared",
                        "Alle dokumentert med referansebrev" if conf == "high" else "Noen referanser er kun egenerklært")
        if len(strong) + len(small) >= n:
            return item(rid, ids(strong + small), "met", "low",
                        f"{len(strong)} references meet the size; {len(small)} more are in scope but smaller than "
                        f"NOK {check['min_value'] / M:g}m",
                        f"{len(strong)} referanser oppfyller størrelsen; {len(small)} til er relevante, men mindre enn "
                        f"NOK {check['min_value'] / M:g} mill.",
                        "Comparability of the smaller references is a judgement call",
                        "Om de mindre referansene er sammenlignbare, er et skjønnsspørsmål")
        if strong or small:
            return item(rid, ids(strong + small), "partly_met", "high",
                        f"Only {len(strong) + len(small)} of {n} required comparable references",
                        f"Bare {len(strong) + len(small)} av {n} påkrevde sammenlignbare referanser",
                        "The count is unambiguous", "Antallet er entydig")
        if related:
            return item(rid, ids(related), "not_met", "low",
                        f"No reference in the required scope; {len(related)} in a related CPV division",
                        f"Ingen referanse innenfor kravet; {len(related)} i en beslektet CPV-hovedgruppe",
                        "Whether related work counts as comparable is uncertain",
                        "Usikkert om beslektet arbeid regnes som sammenlignbart")
        return item(rid, "reference_1–4", "not_met", "high", "No reference in the required scope",
                    "Ingen referanse innenfor kravet", "No overlap at all", "Ingen overlapp")
    if rule == "language":
        e = f("working_languages")
        ok = e["structured"].get("all_staff_norwegian")
        return item(rid, "working_languages", "met" if ok else "partly_met", "high",
                    "All staff work in Norwegian" if ok else "Not all staff work in Norwegian",
                    "Alle ansatte arbeider på norsk" if ok else "Ikke alle ansatte arbeider på norsk",
                    "Explicit in the profile", "Står eksplisitt i profilen")
    if rule == "approval":
        e = f("sector_approval")
        if e is None:
            return item(rid, "none", "lacks_data", "high", "No sector approval recorded in the Capability Locker",
                        "Ingen sentral godkjenning registrert i Capability Locker", "No such field for this firm",
                        "Firmaet har ikke dette feltet")
        s = e["structured"]
        if check["scope"] == "design":
            if s.get("design_approval"):
                return item(rid, "sector_approval", "met", "high", f"DiBK approval covers design ({', '.join(s['scope'])})",
                            f"DiBK-godkjenningen dekker prosjektering ({', '.join(s['scope'])})",
                            "Documented scope", "Dokumentert omfang")
            return item(rid, "sector_approval", "not_met", "high",
                        "DiBK approval explicitly excludes design (prosjektering); the profile mentions an external "
                        "designer, but no designer approval or CV is on file",
                        "DiBK-godkjenningen omfatter uttrykkelig ikke prosjektering; profilen nevner ekstern "
                        "prosjekterende, men verken godkjenning eller CV for denne finnes",
                        "Explicit exclusion in the documented approval", "Uttrykkelig unntak i dokumentert godkjenning")
        if "execution" in s.get("scope", []):
            return item(rid, "sector_approval", "met", "high", "DiBK approval covers execution, tiltaksklasse 2",
                        "DiBK-godkjenningen dekker utførelse, tiltaksklasse 2", "Documented scope", "Dokumentert omfang")
        return item(rid, "sector_approval", "not_met", "high", "DiBK approval covers design only, not execution",
                    "DiBK-godkjenningen dekker bare prosjektering, ikke utførelse", "Documented scope",
                    "Dokumentert omfang")
    if rule == "cv":
        e = f("key_personnel_cvs")
        if e["proof_status"] == "Declared missing":
            return item(rid, "key_personnel_cvs", "lacks_data", "medium", "No CVs prepared (declared missing)",
                        "Ingen CV-er utarbeidet (erklært manglende)",
                        "Staff exist (see staff field) but no CVs are recorded",
                        "Personell finnes (se bemanningsfeltet), men ingen CV-er er registrert")
        if e["proof_status"] == "Documented (n of m)":
            return item(rid, "key_personnel_cvs", "partly_met", "high",
                        f"CVs held for {e['documented_n']} of {e['documented_m']} roles; "
                        f"missing: {', '.join(e['structured']['missing'])}",
                        f"CV finnes for {e['documented_n']} av {e['documented_m']} roller; "
                        f"mangler: {', '.join(e['structured']['missing'])}",
                        "Explicit n-of-m proof status", "Eksplisitt n-av-m-status")
        return item(rid, "key_personnel_cvs", "met", "high", f"CVs held: {', '.join(e['structured']['held'])}",
                    f"CV-er finnes: {', '.join(e['structured']['held'])}", "Documented field", "Dokumentert felt")
    if rule == "pm_experience":
        e = f("key_personnel_cvs")
        if "project manager" in e["structured"].get("held", []):
            return item(rid, "key_personnel_cvs", "partly_met", "low",
                        "Project manager's CV is held, but the Capability Locker does not record years of experience",
                        "CV for prosjektleder finnes, men Capability Locker registrerer ikke antall års erfaring",
                        "Experience length must be read from the CV itself", "Erfaringslengden må leses i selve CV-en")
        return item(rid, "key_personnel_cvs", "lacks_data", "medium", "No project manager CV recorded",
                    "Ingen CV for prosjektleder registrert", "Field does not cover the role", "Feltet dekker ikke rollen")
    if rule == "staff_trade":
        e = f("staff")
        txt = e["value"].lower()
        if "carpenters with trade certificate" in txt:
            return item(rid, "staff", "met", "medium", "9 carpenters with trade certificate (self-declared)",
                        "9 tømrere med fagbrev (egenerklært)", "Self-declared staff list", "Egenerklært bemanning")
        return item(rid, "staff", "not_met", "medium", "No carpenters with trade certificate in the staff list",
                    "Ingen tømrere med fagbrev i bemanningslisten", "Self-declared staff list; firm could hire",
                    "Egenerklært bemanning; firmaet kan ansette")
    if rule == "startbank":
        e = f("startbank_achilles")
        sb = next(p for p in e["parts"] if p["part"] == "StartBANK")
        if not sb.get("registered"):
            return item(rid, "startbank_achilles", "not_met", "high", "Not registered in StartBANK",
                        "Ikke registrert i StartBANK", "Explicit in the profile", "Står eksplisitt i profilen", "StartBANK")
        exp = parse_date(sb["expiry_date"])
        if exp and exp < deadline:
            return item(rid, "startbank_achilles", "partly_met", "medium",
                        f"Registered in StartBANK, but the registration expired {exp} (renewal not completed)",
                        f"Registrert i StartBANK, men registreringen utløp {exp} (fornyelse ikke fullført)",
                        "Renewal could be completed before the deadline", "Fornyelse kan fullføres før fristen",
                        "StartBANK")
        return item(rid, "startbank_achilles", "met", "high", "Registered in StartBANK", "Registrert i StartBANK",
                    "Documented registration", "Dokumentert registrering", "StartBANK")
    if rule == "apprentice":
        e = f("approved_apprentice")
        if e["structured"].get("approved"):
            return item(rid, "approved_apprentice", "met", "high", f"Approved apprentice company ({e['structured']['scope']})",
                        f"Godkjent lærebedrift ({e['structured']['scope']})", "Documented approval", "Dokumentert godkjenning")
        return item(rid, "approved_apprentice", "not_met", "high", "Not an approved apprentice company (no apprentices)",
                    "Ikke godkjent lærebedrift (ingen lærlinger)", "Explicit 'not applicable'", "Eksplisitt «ikke relevant»")
    if rule == "iso14001":
        e = f("environmental_certificate")
        if e is None:
            return item(rid, "none", "lacks_data", "high", "No environmental certificate field in the Capability Locker",
                        "Intet felt for miljøsertifikat i Capability Locker", "No field exists", "Feltet finnes ikke")
        return item(rid, "environmental_certificate", "met", "high", f"ISO 14001 held ({e['structured']['scope']})",
                    f"ISO 14001 finnes ({e['structured']['scope']})", "Documented certificate", "Dokumentert sertifikat")
    if rule == "iso9001":
        e = f("quality_certificate")
        if e is not None:
            return item(rid, "quality_certificate", "not_met", "high", "ISO 9001 explicitly not held",
                        "ISO 9001 finnes uttrykkelig ikke", "Explicit in the profile", "Står eksplisitt i profilen")
        if f("sector_approval") is not None:
            return item(rid, "none", "lacks_data", "low",
                        "No quality-certificate field; the central approval implies a quality system, but no ISO 9001 "
                        "certificate is recorded",
                        "Intet felt for kvalitetssertifikat; sentral godkjenning forutsetter et kvalitetssystem, men "
                        "ISO 9001 er ikke registrert",
                        "Indirect evidence only; 'or equivalent' may apply", "Bare indirekte holdepunkt; «tilsvarende» kan gjelde")
        return item(rid, "none", "lacks_data", "medium", "No quality-certificate field in the Capability Locker",
                    "Intet felt for kvalitetssertifikat i Capability Locker", "No field exists", "Feltet finnes ikke")
    if rule == "ysk":
        e = f("driver_competence_ysk")
        if e is None:
            return item(rid, "none", "lacks_data", "high", "No driver-competence field", "Intet felt for sjåførkompetanse",
                        "No field exists", "Feltet finnes ikke")
        s = e["structured"]
        return item(rid, "driver_competence_ysk", "met", "high", f"{s['certified']} of {s['of']} drivers hold YSK",
                    f"{s['certified']} av {s['of']} sjåfører har YSK", "Documented", "Dokumentert")
    if rule == "equity":
        e = f("equity_ratio")
        ok = e["structured"]["percent"] >= check["min_pct"]
        return item(rid, "equity_ratio", "met" if ok else "not_met", "high",
                    f"Equity ratio {e['structured']['percent']} % ({'≥' if ok else '<'} {check['min_pct']} %)",
                    f"Egenkapitalandel {e['structured']['percent']} % ({'≥' if ok else '<'} {check['min_pct']} %)",
                    "Documented annual accounts", "Dokumenterte årsregnskap")
    if rule == "no_field":
        return item(rid, "none", "lacks_data", "high",
                    f"No Capability Locker field covers {check['topic']} (Table A1 gap) — not silently matched",
                    f"Ingen felt i Capability Locker dekker {check['topic']} (mangel i tabell A1) — ikke stilltiende matchet",
                    "Certain that the data are missing", "Sikkert at dataene mangler")
    raise ValueError(f"no mock rule {rule!r}")


def compare(notice_id: str, lot_id: str | None, reqs: list[dict], checks: dict, profile: dict, deadline: date,
            prompt_version: str) -> dict:
    items, parts = [], {}
    for r in reqs:
        it, part = classify(r, checks[r["req_id"]], profile, deadline)
        items.append(it)
        if part:
            parts[r["req_id"]] = part
    out = {"firm_id": profile["profile_id"], "notice_id": notice_id, "lot_id": lot_id, "prompt_version": prompt_version,
           "model": MOCK_MODEL, "items": items, "mock": True}
    ok, validated, errs = schemas.validate(schemas.ComparisonOutput, out)
    return {"raw": out, "schema_ok": ok, "schema_errors": errs, "validated": validated, "parts": parts}


def prompt_input(notice_rec: dict, reqs: list[dict], profile: dict, lot_id: str | None) -> dict:
    """Exactly what the matching + classification prompt receives: stored requirements, the Capability Locker
    (no Account/Baseline sections) and notice context."""
    o = notice_rec["original"]
    return {"notice_context": {k: o.get(k, "") for k in ("doffin_id", "title", "tender_deadline_utc", "lot_count",
                                                         "estimated_value", "currency")} | {"lot_id": lot_id},
            "requirements": [{k: r[k] for k in ("req_id", "lot_id", "category", "text_summary_en", "mandatory",
                                                "proof_demanded", "proof_type")} | {"cited_text": (r.get("source") or {}).get("cited_text")}
                             for r in reqs],
            "capability_locker": [{"id": e["id"], "label": e["label_en"], "value": e["value"],
                                   "proof_status": e["proof_status_original"], "last_updated": e["last_updated"],
                                   "expiry": e["expiry_original"]} for e in profile["capability_locker"]]}
